arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Content-Type: application/json' -d '{"token":"***","exclude_archived":false,"types":"public_channel,private_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(1)
for c in d['channels']:
    if 'incident' in c.get('name','').lower() or 'checkout' in c.get('name','').lower() or 'outage' in c.get('name','').lower() or 'inc-' in c.get('name','').lower():
        print(c['id'], '|', c['name'], '| archived=', c.get('is_archived'), '| topic=', c.get('topic',''))
"

